function validate([root]) {
  if (!root.length || root[0] === null) return 'The tree needs at least two nodes.';
  const left = [], right = [], values = [];
  let parent = 0, side = 0;
  for (let i = 0; i < root.length; i++) {
    if (i > 0) {
      while (root[parent] === null) parent++;
      const child = root[i] === null ? -1 : i;
      if (side === 0) left[parent] = child; else { right[parent] = child; parent++; }
      side = 1 - side;
    }
    if (root[i] !== null) values.push(root[i]);
  }
  if (values.length < 2 || values.length > 1000) return 'The tree has 2 to 1000 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < -2147483648 || v > 2147483647)) return 'Node values are 32-bit integers.';
  const inorder = [], stack = [];
  let index = 0;
  while (index !== -1 && index !== undefined || stack.length) {
    while (index !== -1 && index !== undefined) { stack.push(index); index = left[index]; }
    index = stack.pop();
    inorder.push(root[index]);
    index = right[index];
  }
  const sorted = [...inorder].sort((a, b) => a - b);
  if (sorted.some((v, i) => i > 0 && v === sorted[i - 1])) return 'Node values must be distinct.';
  if (inorder.filter((v, i) => v !== sorted[i]).length !== 2) return 'Exactly two node values must be out of place in an otherwise valid search tree.';
  return null;
}

