  const deep = !large && rand() < 0.3;
  const nodes = [{ val: 0, left: null, right: null }];
  while (nodes.length < count) {
    const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(2))] : nodes[pick(nodes.length)];
    const side = rand() < 0.5 ? 'left' : 'right';
    if (parent[side]) continue;
    const node = { val: 0, left: null, right: null };
    parent[side] = node;
    nodes.push(node);
  }
  // Distinct values, sometimes including the 32-bit extremes.
  const span = large ? 1000000000 : (rand() < 0.5 ? 20 : 1000);
  const values = new Set();
  if (!large && rand() < 0.25) values.add(-2147483648);
  if (!large && rand() < 0.25) values.add(2147483647);
  while (values.size < count) values.add(pick(2 * span + 1) - span);
  const sorted = [...values].sort((a, b) => a - b);
  // Write the sorted values in in-order, which makes a valid BST.
  const order = [];
  const stack = [];
  let node = nodes[0];
  while (node || stack.length) {
    while (node) { stack.push(node); node = node.left; }
    node = stack.pop();
    order.push(node);
    node = node.right;
  }
  order.forEach((n, i) => { n.val = sorted[i]; });
  // Exchange two different nodes' values.
  const a = pick(count);
  let b = pick(count - 1);
  if (b >= a) b++;
  [order[a].val, order[b].val] = [order[b].val, order[a].val];
